import { useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

export interface AppearanceSettings {
  theme: string;
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<string, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceScreen({ onChange }: AppearanceScreenProps) {
  const [theme, setTheme] = useState('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  const emit = (next: Partial<AppearanceSettings>) => {
    onChange?.({
      theme,
      scale,
      dense,
      font,
      ...next,
    });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-lg)',
        maxWidth: '480px',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-r)',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme] ?? theme}</JxBadge>
      </div>

      <JxToggle
        items={[
          { value: 'light', label: 'Светлая' },
          { value: 'dark', label: 'Тёмная' },
          { value: 'system', label: 'Системная' },
        ]}
        value={theme}
        onValueChange={(value) => {
          setTheme(value);
          emit({ theme: value });
        }}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={scale}
        onValueChange={(value) => {
          setScale(value);
          emit({ scale: value });
        }}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => {
          const value = event.target.checked;
          setDense(value);
          emit({ dense: value });
        }}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Inter Tight (по умолчанию)' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={font}
        onValueChange={(value) => {
          setFont(value);
          emit({ font: value });
        }}
      />
    </div>
  );
}

